hl.bind(mainMod .. shift .. " + left",
    function()
        local w = hl.get_active_workspace(); if not w then return end; hl.dispatch(hl.dsp.workspace.move({
            workspace = w
                .id,
            monitor = "l"
        }))
    end)
hl.bind(mainMod .. shift .. " + right",
    function()
        local w = hl.get_active_workspace(); if not w then return end; hl.dispatch(hl.dsp.workspace.move({
            workspace = w
                .id,
            monitor = "r"
        }))
    end)
hl.bind(mainMod .. shift .. " + up",
    function()
        local w = hl.get_active_workspace(); if not w then return end; hl.dispatch(hl.dsp.workspace.move({
            workspace = w
                .id,
            monitor = "u"
        }))
    end)
hl.bind(mainMod .. shift .. " + down",
    function()
        local w = hl.get_active_workspace(); if not w then return end; hl.dispatch(hl.dsp.workspace.move({
            workspace = w
                .id,
            monitor = "d"
        }))
    end)

